using System.ComponentModel;
using System.Diagnostics.CodeAnalysis;

namespace SourceGen.Ioc;

/// <summary>
/// The resolver of an <see cref="IEnumerable{T}"/> entry of a collection generated by SourceGen.Ioc, which also exposes
/// the resolver of the collection's array before any fallback services are merged. A container that imports the module
/// uses it to merge the fallback services once, with its own fallback provider; explicit registrations of
/// <see cref="IEnumerable{T}"/> are not wrapped in it and are kept as they are.
/// </summary>
/// <typeparam name="TContainer">The container that generated the collection.</typeparam>
/// <param name="arrayResolver">Resolves the collection's array, without fallback services.</param>
/// <param name="resolver">Resolves the <see cref="IEnumerable{T}"/>, with the container's own fallback services.</param>
[Experimental("SGIOCEXP001", Message = "This type is used by SourceGen.Ioc and may change or be removed in future versions.")]
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed class IocCollectionResolver<TContainer>(Func<TContainer, object> arrayResolver, Func<TContainer, object> resolver)
{
    /// <summary>
    /// Gets the resolver of the collection's array, without fallback services.
    /// </summary>
    public Func<TContainer, object> ArrayResolver { get; } = arrayResolver;

    /// <summary>
    /// Resolves the <see cref="IEnumerable{T}"/> entry.
    /// </summary>
    /// <param name="container">The container (scope) resolving the entry.</param>
    /// <returns>The collection.</returns>
    public object Resolve(TContainer container) => resolver(container);
}
